//! Who may join a swarm, and how devices and coordinators recognise each other.
//!
//! * **Passphrases** are five words from the EFF large wordlist (about 64 bits), generated by
//!   the coordinator, or chosen by the owner.
//! * **Device keys.** Each device has one master secret. For every swarm it derives a separate
//!   Ed25519 identity from it (HKDF with the swarm's id), so two swarms cannot tell they have seen
//!   the same device. The coordinator's swarm key is derived the same way.
//! * **First join** runs SPAKE2 with the passphrase: neither side sends it, and someone recording
//!   the exchange cannot guess it offline. Both sides then prove they derived the same key
//!   (confirmation MACs over the whole transcript, which includes the device's key), so the
//!   coordinator approves that device key and the device pins the coordinator's key.
//! * **Reconnects** need no passphrase: the device signs the coordinator's fresh challenge, and
//!   the coordinator signs the device's. Removing a device is removing its key.
//! * **Model sharing** requests are signed by the requesting device's key (with a timestamp), and
//!   a holder serves only keys the swarm approved: no shared secret ever crosses the network.
//!
//! Not yet: the control channel itself is not encrypted (someone on the network can read, but
//! not join or impersonate). TLS on top of these keys comes later.
use anyhow::{anyhow, bail, Context, Result};
use ed25519_dalek::{Signature, Signer, SigningKey, Verifier, VerifyingKey};
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use spake2::{Ed25519Group, Identity, Password, Spake2};
use std::path::{Path, PathBuf};

const WORDLIST: &str = include_str!("../data/eff_large_wordlist.txt");
const SPAKE_ID_MEMBER: &[u8] = b"clamor-member";
const SPAKE_ID_COORDINATOR: &[u8] = b"clamor-coordinator";

pub fn random_bytes<const N: usize>() -> [u8; N] {
    let mut b = [0u8; N];
    getrandom::fill(&mut b).expect("the OS random number generator");
    b
}

// ---------------------------------------------------------------- passphrases

fn words() -> impl Iterator<Item = &'static str> {
    WORDLIST.lines().filter_map(|l| l.split_whitespace().nth(1))
}

/// Five random words from the EFF large wordlist (7776 words: ~64 bits), joined by hyphens.
pub fn generate_passphrase() -> String {
    let list: Vec<&str> = words().collect();
    (0..5)
        .map(|_| {
            // Rejection sampling: no modulo bias.
            loop {
                let n = u16::from_le_bytes(random_bytes::<2>()) as usize;
                if n < 65536 - 65536 % list.len() {
                    return list[n % list.len()];
                }
            }
        })
        .collect::<Vec<_>>()
        .join("-")
}

/// How a passphrase is compared: lower case, words separated by single hyphens, so
/// "Harbor velvet  crab" and "harbor-velvet-crab" are the same passphrase.
pub fn normalize_passphrase(p: &str) -> String {
    p.split(|c: char| c.is_whitespace() || c == '-' || c == '_' || c == '.').filter(|w| !w.is_empty()).map(|w| w.to_lowercase()).collect::<Vec<_>>().join("-")
}

// ---------------------------------------------------------------- MAC and key derivation

/// HMAC-SHA256 (RFC 2104).
pub fn hmac(key: &[u8], msg: &[u8]) -> [u8; 32] {
    let mut k = [0u8; 64];
    if key.len() > 64 {
        k[..32].copy_from_slice(&Sha256::digest(key));
    } else {
        k[..key.len()].copy_from_slice(key);
    }
    let pad = |b: u8| k.iter().map(|x| x ^ b).collect::<Vec<u8>>();
    let inner = Sha256::new().chain_update(pad(0x36)).chain_update(msg).finalize();
    Sha256::new().chain_update(pad(0x5c)).chain_update(inner).finalize().into()
}

/// HKDF-SHA256 (RFC 5869) for one 32-byte output.
pub fn hkdf32(ikm: &[u8], salt: &[u8], info: &[u8]) -> [u8; 32] {
    let prk = hmac(salt, ikm);
    let mut m = info.to_vec();
    m.push(1);
    hmac(&prk, &m)
}

fn ct_eq(a: &[u8], b: &[u8]) -> bool {
    a.len() == b.len() && a.iter().zip(b).fold(0u8, |acc, (x, y)| acc | (x ^ y)) == 0
}

// ---------------------------------------------------------------- device identity

/// The device's master secret, created on first use (readable only by its owner).
pub struct Device {
    master: [u8; 32],
}

impl Device {
    pub fn load_or_create(config_dir: &Path) -> Result<Self> {
        let path = config_dir.join("device.key");
        if let Ok(b) = std::fs::read(&path) {
            let master: [u8; 32] = b.try_into().map_err(|_| anyhow!("{} is corrupt (expected 32 bytes)", path.display()))?;
            return Ok(Self { master });
        }
        let master = random_bytes::<32>();
        write_private(&path, &master)?;
        Ok(Self { master })
    }

    #[cfg(test)]
    pub fn for_tests(master: [u8; 32]) -> Self {
        Self { master }
    }

    /// This device's identity in one swarm. Different swarms get unrelated keys.
    pub fn swarm_key(&self, swarm_id: &str) -> SigningKey {
        SigningKey::from_bytes(&hkdf32(&self.master, swarm_id.as_bytes(), b"clamor swarm identity v1"))
    }
}

/// Write a file only its owner can read.
pub fn write_private(path: &Path, data: &[u8]) -> Result<()> {
    std::fs::create_dir_all(path.parent().unwrap())?;
    let tmp = path.with_extension("tmp");
    {
        let mut o = std::fs::OpenOptions::new();
        o.write(true).create(true).truncate(true);
        #[cfg(unix)]
        std::os::unix::fs::OpenOptionsExt::mode(&mut o, 0o600);
        use std::io::Write;
        o.open(&tmp).with_context(|| format!("writing {}", tmp.display()))?.write_all(data)?;
    }
    std::fs::rename(&tmp, path)?;
    Ok(())
}

pub fn key_hex(k: &VerifyingKey) -> String {
    hex::encode(k.to_bytes())
}

pub fn parse_key(s: &str) -> Result<VerifyingKey> {
    let b: [u8; 32] = hex::decode(s)?.try_into().map_err(|_| anyhow!("a key is 32 bytes"))?;
    VerifyingKey::from_bytes(&b).map_err(|e| anyhow!("bad key: {e}"))
}

fn parse_sig(s: &str) -> Result<Signature> {
    let b: [u8; 64] = hex::decode(s)?.try_into().map_err(|_| anyhow!("a signature is 64 bytes"))?;
    Ok(Signature::from_bytes(&b))
}

// ---------------------------------------------------------------- swarm profiles

/// What a coordinator keeps about its swarm.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct CoordinatorProfile {
    pub swarm_id: String,
    pub name: String,
    pub passphrase: String,
    pub approved: Vec<ApprovedDevice>,
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct ApprovedDevice {
    /// The device's key in this swarm (hex).
    pub key: String,
    pub name: String,
    pub approved_unix: u64,
}

/// What a device keeps about a swarm it joined.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct MemberProfile {
    pub swarm_id: String,
    pub name: String,
    /// The coordinator's key, pinned at first join.
    pub coordinator_key: String,
    /// Where the coordinator was reached, most recent first.
    pub addresses: Vec<String>,
    pub last_joined_unix: u64,
}

fn swarms_dir(config_dir: &Path) -> PathBuf {
    config_dir.join("swarms")
}

fn load_json<T: for<'de> Deserialize<'de>>(p: &Path) -> Option<T> {
    serde_json::from_slice(&std::fs::read(p).ok()?).ok()
}

impl CoordinatorProfile {
    fn path(config_dir: &Path, swarm_id: &str) -> PathBuf {
        swarms_dir(config_dir).join(format!("coordinator-{swarm_id}.json"))
    }
    /// The swarm this device coordinates under `name`, or a new one (new id, passphrase).
    pub fn load_or_create(config_dir: &Path, name: &str, passphrase: Option<&str>) -> Result<Self> {
        let existing = Self::all(config_dir).into_iter().find(|p| p.name == name);
        let mut p = existing.unwrap_or_else(|| CoordinatorProfile { swarm_id: hex::encode(random_bytes::<16>()), name: name.into(), passphrase: generate_passphrase(), approved: Vec::new() });
        if let Some(pp) = passphrase {
            let pp = normalize_passphrase(pp);
            if pp.is_empty() {
                bail!("the passphrase is empty");
            }
            p.passphrase = pp;
        }
        p.save(config_dir)?;
        Ok(p)
    }
    pub fn save(&self, config_dir: &Path) -> Result<()> {
        write_private(&Self::path(config_dir, &self.swarm_id), &serde_json::to_vec_pretty(self)?)
    }
    pub fn all(config_dir: &Path) -> Vec<Self> {
        let mut v: Vec<Self> = std::fs::read_dir(swarms_dir(config_dir))
            .into_iter()
            .flatten()
            .flatten()
            .filter(|e| e.file_name().to_string_lossy().starts_with("coordinator-"))
            .filter_map(|e| load_json(&e.path()))
            .collect();
        v.sort_by(|a: &Self, b| a.name.cmp(&b.name));
        v
    }
}

impl MemberProfile {
    fn path(config_dir: &Path, swarm_id: &str) -> PathBuf {
        swarms_dir(config_dir).join(format!("member-{swarm_id}.json"))
    }
    pub fn load(config_dir: &Path, swarm_id: &str) -> Option<Self> {
        load_json(&Self::path(config_dir, swarm_id))
    }
    pub fn all(config_dir: &Path) -> Vec<Self> {
        let mut v: Vec<Self> = std::fs::read_dir(swarms_dir(config_dir))
            .into_iter()
            .flatten()
            .flatten()
            .filter(|e| e.file_name().to_string_lossy().starts_with("member-"))
            .filter_map(|e| load_json(&e.path()))
            .collect();
        v.sort_by_key(|p: &Self| std::cmp::Reverse(p.last_joined_unix));
        v
    }
    pub fn save(&self, config_dir: &Path) -> Result<()> {
        write_private(&Self::path(config_dir, &self.swarm_id), &serde_json::to_vec_pretty(self)?)
    }
}

// ---------------------------------------------------------------- the handshake

/// Everything both sides sign or MAC, so no part of the exchange can be swapped.
#[allow(clippy::too_many_arguments)]
fn transcript(role: &str, swarm_id: &str, coordinator_key: &str, nonce_c: &str, nonce_m: &str, device_key: &str, spake_b: &str, spake_a: &str) -> Vec<u8> {
    format!("clamor-auth-v1|{role}|{swarm_id}|{coordinator_key}|{nonce_c}|{nonce_m}|{device_key}|{spake_b}|{spake_a}").into_bytes()
}

/// Coordinator side of one connection's authentication.
pub struct CoordinatorHandshake {
    pub swarm_id: String,
    pub coordinator_key: String,
    pub nonce_c: String,
    pub spake_b: String,
    spake: Spake2<Ed25519Group>,
}

/// What the coordinator sends first.
#[derive(Clone, Debug)]
pub struct Challenge {
    pub swarm_id: String,
    pub swarm_name: String,
    pub coordinator_key: String,
    pub nonce: String,
    pub spake: String,
}

/// The device's answer.
#[derive(Clone, Debug)]
pub struct Proof {
    pub device_key: String,
    pub signature: String,
    /// First join only: SPAKE2 message and key confirmation.
    pub spake: Option<String>,
    pub confirm: Option<String>,
}

/// The coordinator's closing proof (in Welcome).
#[derive(Clone, Debug)]
pub struct CoordinatorProof {
    pub signature: String,
    pub confirm: Option<String>,
}

#[derive(Debug)]
pub enum Verdict {
    /// A device the swarm already approved.
    Known,
    /// A new device that proved it knows the passphrase: approve its key.
    Approve,
}

impl CoordinatorHandshake {
    pub fn start(swarm_id: &str, swarm_name: &str, key: &SigningKey, passphrase: &str) -> (Self, Challenge) {
        let (spake, msg) = Spake2::<Ed25519Group>::start_b(&Password::new(passphrase.as_bytes()), &Identity::new(SPAKE_ID_MEMBER), &Identity::new(SPAKE_ID_COORDINATOR));
        let (coordinator_key, nonce_c, spake_b) = (key_hex(&key.verifying_key()), hex::encode(random_bytes::<16>()), hex::encode(msg));
        let ch = Challenge { swarm_id: swarm_id.into(), swarm_name: swarm_name.into(), coordinator_key: coordinator_key.clone(), nonce: nonce_c.clone(), spake: spake_b.clone() };
        (Self { swarm_id: swarm_id.into(), coordinator_key, nonce_c, spake_b, spake }, ch)
    }

    /// Check the device's proof. `approved` says whether a key is already approved. Returns the
    /// verdict and the coordinator's closing proof.
    pub fn verify(self, key: &SigningKey, nonce_m: &str, proof: &Proof, approved: impl Fn(&str) -> bool) -> Result<(Verdict, CoordinatorProof)> {
        let device = parse_key(&proof.device_key)?;
        let spake_a = proof.spake.clone().unwrap_or_default();
        let t = |role| transcript(role, &self.swarm_id, &self.coordinator_key, &self.nonce_c, nonce_m, &proof.device_key, &self.spake_b, &spake_a);
        device.verify(&t("member"), &parse_sig(&proof.signature)?).map_err(|_| anyhow!("the device's signature does not verify"))?;
        let mine = hex::encode(key.sign(&t("coordinator")).to_bytes());
        let known = approved(&proof.device_key);
        let verdict = if known { Verdict::Known } else { Verdict::Approve };
        // A device that sent the passphrase gets it checked even if it is already approved: it
        // may be re-pinning a coordinator whose key it does not know.
        let (Some(a), Some(confirm)) = (&proof.spake, &proof.confirm) else {
            if known {
                return Ok((verdict, CoordinatorProof { signature: mine, confirm: None }));
            }
            bail!("this device is not approved in this swarm: join with the swarm's passphrase");
        };
        let shared = self.spake.finish(&hex::decode(a)?).map_err(|_| anyhow!("bad SPAKE2 message"))?;
        if !ct_eq(&hmac(&shared, &t("member-confirm")), &hex::decode(confirm)?) {
            bail!("wrong passphrase");
        }
        Ok((verdict, CoordinatorProof { signature: mine, confirm: Some(hex::encode(hmac(&shared, &t("coordinator-confirm")))) }))
    }
}

/// Device side. `pinned`: the coordinator key remembered for this swarm, if any.
pub struct MemberHandshake {
    ch: Challenge,
    nonce_m: String,
    device_key: String,
    spake_a: String,
    shared: Option<Vec<u8>>,
}

impl MemberHandshake {
    /// Answer a challenge. With a pinned key that matches and no passphrase, sign only;
    /// otherwise the passphrase is required and SPAKE2 runs.
    pub fn answer(ch: &Challenge, nonce_m: &str, key: &SigningKey, pinned: Option<&str>, passphrase: Option<&str>) -> Result<(Self, Proof)> {
        let device_key = key_hex(&key.verifying_key());
        let known = pinned == Some(ch.coordinator_key.as_str());
        if pinned.is_some() && !known && passphrase.is_none() {
            bail!("this swarm's coordinator key changed since you joined (a different coordinator, or someone impersonating it); rejoin with the passphrase if you expected this");
        }
        let (spake_a, shared) = if known && passphrase.is_none() {
            (String::new(), None)
        } else {
            let pw = normalize_passphrase(passphrase.ok_or_else(|| anyhow!("first join: this needs the swarm's passphrase (--passphrase)"))?);
            let (st, msg) = Spake2::<Ed25519Group>::start_a(&Password::new(pw.as_bytes()), &Identity::new(SPAKE_ID_MEMBER), &Identity::new(SPAKE_ID_COORDINATOR));
            let shared = st.finish(&hex::decode(&ch.spake)?).map_err(|_| anyhow!("bad SPAKE2 message from the coordinator"))?;
            (hex::encode(msg), Some(shared))
        };
        let t = |role| transcript(role, &ch.swarm_id, &ch.coordinator_key, &ch.nonce, nonce_m, &device_key, &ch.spake, &spake_a);
        let signature = hex::encode(key.sign(&t("member")).to_bytes());
        let confirm = shared.as_ref().map(|k| hex::encode(hmac(k, &t("member-confirm"))));
        let proof = Proof { device_key: device_key.clone(), signature, spake: (!spake_a.is_empty()).then(|| spake_a.clone()), confirm };
        Ok((Self { ch: ch.clone(), nonce_m: nonce_m.into(), device_key, spake_a, shared }, proof))
    }

    /// Check the coordinator's closing proof. On a first join this is what proves the
    /// coordinator knew the passphrase too, so its key can be pinned.
    pub fn finish(self, p: &CoordinatorProof) -> Result<()> {
        let t = |role| transcript(role, &self.ch.swarm_id, &self.ch.coordinator_key, &self.ch.nonce, &self.nonce_m, &self.device_key, &self.ch.spake, &self.spake_a);
        parse_key(&self.ch.coordinator_key)?.verify(&t("coordinator"), &parse_sig(&p.signature)?).map_err(|_| anyhow!("the coordinator's signature does not verify"))?;
        if let Some(k) = &self.shared {
            let c = p.confirm.as_ref().ok_or_else(|| anyhow!("the coordinator did not confirm the passphrase"))?;
            if !ct_eq(&hmac(k, &t("coordinator-confirm")), &hex::decode(c)?) {
                bail!("the coordinator could not prove it knows the passphrase");
            }
        }
        Ok(())
    }
}

// ---------------------------------------------------------------- signed sharing requests

pub const SHARE_AUTH_HEADER: &str = "x-clamor-auth";
const SHARE_WINDOW_SECS: u64 = 300;

fn now() -> u64 {
    clamor_proto::unix_now()
}

/// `x-clamor-auth` for a request to `path`: "<key hex>:<unix time>:<signature hex>".
pub fn sign_share_request(key: &SigningKey, path: &str) -> String {
    let ts = now();
    let sig = key.sign(format!("clamor-share-v1|{ts}|{path}").as_bytes());
    format!("{}:{ts}:{}", key_hex(&key.verifying_key()), hex::encode(sig.to_bytes()))
}

/// Check a sharing request's header; returns the requesting key if it is allowed.
pub fn verify_share_request(header: &str, path: &str, allowed: impl Fn(&str) -> bool) -> Result<String> {
    let mut parts = header.splitn(3, ':');
    let (k, ts, sig) = (parts.next().unwrap_or(""), parts.next().unwrap_or(""), parts.next().unwrap_or(""));
    let ts: u64 = ts.parse().map_err(|_| anyhow!("bad timestamp"))?;
    if now().abs_diff(ts) > SHARE_WINDOW_SECS {
        bail!("request too old (or clocks more than 5 minutes apart)");
    }
    if !allowed(k) {
        bail!("not a device of this swarm");
    }
    parse_key(k)?.verify(format!("clamor-share-v1|{ts}|{path}").as_bytes(), &parse_sig(sig)?).map_err(|_| anyhow!("bad signature"))?;
    Ok(k.to_string())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn passphrases() {
        assert_eq!(words().count(), 7776);
        let p = generate_passphrase();
        assert_eq!(p.split('-').count(), 5, "{p}");
        assert_ne!(p, generate_passphrase());
        assert_eq!(normalize_passphrase("  Harbor velvet__crab-Lantern.ninety "), "harbor-velvet-crab-lantern-ninety");
    }

    #[test]
    fn hmac_and_hkdf_match_the_rfc_vectors() {
        // RFC 4231 test case 2.
        assert_eq!(hex::encode(hmac(b"Jefe", b"what do ya want for nothing?")), "5bdcc146bf60754e6a042426089575c75a003f089d2739839dec58b964ec3843");
        // RFC 5869 test case 1 (first 32 bytes of OKM).
        let ikm = [0x0bu8; 22];
        let salt = hex::decode("000102030405060708090a0b0c").unwrap();
        let info = hex::decode("f0f1f2f3f4f5f6f7f8f9").unwrap();
        assert_eq!(hex::encode(hkdf32(&ikm, &salt, &info)), "3cb25f25faacd57a90434f64d0362f2a2d2d0a90cf1a5a4c5db02d56ecc4c5bf");
    }

    #[test]
    fn swarm_identities_are_stable_and_unlinkable() {
        let d = Device { master: [7; 32] };
        assert_eq!(d.swarm_key("home").verifying_key(), d.swarm_key("home").verifying_key());
        assert_ne!(d.swarm_key("home").verifying_key(), d.swarm_key("work").verifying_key());
        assert_ne!(Device { master: [8; 32] }.swarm_key("home").verifying_key(), d.swarm_key("home").verifying_key());
    }

    fn keys() -> (SigningKey, SigningKey) {
        (Device { master: [1; 32] }.swarm_key("s"), Device { master: [2; 32] }.swarm_key("s"))
    }

    #[test]
    fn first_join_with_the_right_passphrase_then_reconnect_without_it() {
        let (ck, dk) = keys();
        // First join.
        let (hs, ch) = CoordinatorHandshake::start("s", "home", &ck, "harbor-velvet-crab");
        let (m, proof) = MemberHandshake::answer(&ch, "n1", &dk, None, Some("Harbor Velvet Crab")).unwrap();
        let (v, cp) = hs.verify(&ck, "n1", &proof, |_| false).unwrap();
        assert!(matches!(v, Verdict::Approve));
        m.finish(&cp).unwrap();
        // Reconnect: pinned key, no passphrase, key already approved.
        let dkey = key_hex(&dk.verifying_key());
        let (hs, ch) = CoordinatorHandshake::start("s", "home", &ck, "harbor-velvet-crab");
        let (m, proof) = MemberHandshake::answer(&ch, "n2", &dk, Some(&ch.coordinator_key), None).unwrap();
        assert!(proof.spake.is_none(), "the passphrase is not used on reconnect");
        let (v, cp) = hs.verify(&ck, "n2", &proof, |k| k == dkey).unwrap();
        assert!(matches!(v, Verdict::Known));
        m.finish(&cp).unwrap();
    }

    /// A known device that gives the passphrase again (e.g. the coordinator was reinstalled
    /// and has a new key) proves it and re-pins; a wrong one is refused even for a known key.
    #[test]
    fn known_devices_can_reprove_the_passphrase() {
        let (ck, dk) = keys();
        let dkey = key_hex(&dk.verifying_key());
        let (hs, ch) = CoordinatorHandshake::start("s", "home", &ck, "pass-phrase");
        let (m, proof) = MemberHandshake::answer(&ch, "n", &dk, Some("0".repeat(64).as_str()), Some("pass-phrase")).unwrap();
        let (v, cp) = hs.verify(&ck, "n", &proof, |k| k == dkey).unwrap();
        assert!(matches!(v, Verdict::Known) && cp.confirm.is_some());
        m.finish(&cp).unwrap();
        let (hs, ch) = CoordinatorHandshake::start("s", "home", &ck, "pass-phrase");
        let (_, proof) = MemberHandshake::answer(&ch, "n", &dk, Some(&ch.coordinator_key), Some("wrong")).unwrap();
        assert!(hs.verify(&ck, "n", &proof, |k| k == dkey).is_err());
    }

    #[test]
    fn wrong_passphrase_and_unapproved_devices_are_refused() {
        let (ck, dk) = keys();
        let (hs, ch) = CoordinatorHandshake::start("s", "home", &ck, "right-words-here");
        let (_, proof) = MemberHandshake::answer(&ch, "n", &dk, None, Some("wrong-words-here")).unwrap();
        assert!(hs.verify(&ck, "n", &proof, |_| false).unwrap_err().to_string().contains("wrong passphrase"));
        // A device that skips the passphrase is not let in.
        let (hs, ch) = CoordinatorHandshake::start("s", "home", &ck, "right-words-here");
        let (_, proof) = MemberHandshake::answer(&ch, "n", &dk, Some(&ch.coordinator_key), None).unwrap();
        assert!(hs.verify(&ck, "n", &proof, |_| false).unwrap_err().to_string().contains("not approved"));
    }

    #[test]
    fn an_impostor_coordinator_is_detected() {
        let (ck, dk) = keys();
        let impostor = Device { master: [9; 32] }.swarm_key("s");
        // The device pinned the real coordinator; an impostor's challenge is refused outright.
        let (_, ch) = CoordinatorHandshake::start("s", "home", &impostor, "x");
        let real = key_hex(&ck.verifying_key());
        assert!(MemberHandshake::answer(&ch, "n", &dk, Some(&real), None).is_err());
        // On a first join, an impostor that does not know the passphrase cannot confirm it.
        let (hs, ch) = CoordinatorHandshake::start("s", "home", &impostor, "guessed-wrong");
        let (m, proof) = MemberHandshake::answer(&ch, "n", &dk, None, Some("right-words")).unwrap();
        assert!(hs.verify(&impostor, "n", &proof, |_| false).is_err());
        let forged = CoordinatorProof { signature: hex::encode(impostor.sign(b"whatever").to_bytes()), confirm: Some("00".repeat(32)) };
        assert!(m.finish(&forged).is_err());
    }

    #[test]
    fn tampering_with_the_exchange_breaks_it() {
        let (ck, dk) = keys();
        let (hs, ch) = CoordinatorHandshake::start("s", "home", &ck, "pass-phrase");
        let (_, mut proof) = MemberHandshake::answer(&ch, "n", &dk, None, Some("pass-phrase")).unwrap();
        // Swap in another device's key: the signature no longer matches.
        proof.device_key = key_hex(&Device { master: [3; 32] }.swarm_key("s").verifying_key());
        assert!(hs.verify(&ck, "n", &proof, |_| false).is_err());
    }

    #[test]
    fn share_requests_are_signed_fresh_and_by_a_swarm_device() {
        let (_, dk) = keys();
        let k = key_hex(&dk.verifying_key());
        let h = sign_share_request(&dk, "/models/m.gguf/slice?start=0&end=2&embed=false");
        assert_eq!(verify_share_request(&h, "/models/m.gguf/slice?start=0&end=2&embed=false", |x| x == k).unwrap(), k);
        assert!(verify_share_request(&h, "/models/other.gguf/slice?start=0&end=2&embed=false", |x| x == k).is_err(), "bound to the path");
        assert!(verify_share_request(&h, "/models/m.gguf/slice?start=0&end=2&embed=false", |_| false).is_err(), "unknown device");
        let old = format!("{k}:1000:{}", hex::encode(dk.sign(b"clamor-share-v1|1000|/x").to_bytes()));
        assert!(verify_share_request(&old, "/x", |x| x == k).is_err(), "stale");
    }
}
